/**
 * Engine selection and text tidy-up.
 *
 * Two engines are registered; `wasm` is the one guaranteed to be there, `native` is
 * a fast path that only exists on browsers where the Shape Detection API has been
 * switched on. "Automatic" tries native and quietly falls back the moment it fails
 * or comes back suspiciously empty.
 */
import * as wasm from './engine-wasm.js';
import * as native from './engine-native.js';

export const engines = { wasm, native };

/** Enough characters that we believe the native detector actually read something. */
const NATIVE_MIN_CHARS = 4;

export async function recognize(image, options) {
  const { engine = 'auto' } = options;
  const started = performance.now();

  const run = async (impl) => {
    const result = await impl.recognize(image, options);
    return { ...result, ms: Math.round(performance.now() - started) };
  };

  if (engine === 'native') return run(native);
  if (engine === 'wasm' || !native.available()) return run(wasm);

  try {
    const result = await run(native);
    if (result.text.trim().length >= NATIVE_MIN_CHARS) return result;
  } catch {
    // fall through to WASM
  }
  return run(wasm);
}

export const terminate = () => Promise.all([wasm.terminate(), native.terminate()]);

/**
 * OCR emits one line per visual line, which is what you want for receipts and code
 * but not for prose you are about to paste somewhere. This rejoins wrapped lines
 * inside a paragraph (blank lines keep paragraphs apart) and repairs end-of-line
 * hyphenation.
 */
export function joinWrappedLines(text) {
  return text
    .split(/\n{2,}/)
    .map((paragraph) =>
      paragraph
        .split('\n')
        .map((line) => line.trim())
        .filter(Boolean)
        .reduce((acc, line) => {
          if (!acc) return line;
          return /[\p{Ll}\p{Nd}]-$/u.test(acc) ? acc.slice(0, -1) + line : `${acc} ${line}`;
        }, ''),
    )
    .filter(Boolean)
    .join('\n\n');
}

/** Strip the page-break characters and trailing spaces tesseract leaves behind. */
export function clean(text) {
  return text
    .replace(/\f/g, '')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

export function summarise({ text, confidence, ms, engine }) {
  const words = text.trim() ? text.trim().split(/\s+/).length : 0;
  const parts = [
    `${words} word${words === 1 ? '' : 's'}`,
    `${text.length} character${text.length === 1 ? '' : 's'}`,
  ];
  if (typeof confidence === 'number' && Number.isFinite(confidence)) {
    parts.push(`${Math.round(confidence)}% confidence`);
  }
  parts.push(`${(ms / 1000).toFixed(1)}s`);
  parts.push(engine === 'native' ? 'native engine' : 'on-device engine');
  return parts.join(' · ');
}
