/**
 * Wiring: pick an image (camera, gallery, file dialog, drag/drop, paste, share
 * target, file handler) → draw it to a canvas → OCR the canvas → show the text.
 *
 * `BASE` is resolved from this module's own URL rather than hardcoded to "/", so the
 * app works when served from a sub-path too. The entry module sits at the site root
 * both in dev (src/app.js) and in the build output (dist/app.js), so this is stable.
 */
import * as ocr from './lib/ocr.js';
import * as camera from './lib/camera.js';
import { decode, render, imageFromTransfer } from './lib/image.js';

const BASE = new URL('./', import.meta.url);
const SHARE_CACHE = 'shared-image';

/** Phones get the camera by default; mice and trackpads get the file picker. */
const TOUCH = matchMedia('(hover: none) and (pointer: coarse)').matches;

const $ = (id) => document.getElementById(id);
const el = {
  camera: $('camera'),
  viewfinder: $('viewfinder'),
  btnShutter: $('btn-shutter'),
  btnTorch: $('btn-torch'),
  btnUploadInstead: $('btn-upload-instead'),
  btnBackToCamera: $('btn-back-to-camera'),
  cameraNote: $('camera-note'),

  source: $('source'),
  dropzone: $('dropzone'),
  firstRun: $('first-run'),
  btnCamera: $('btn-camera'),
  btnChoose: $('btn-choose'),
  cameraInput: $('camera-input'),
  fileInput: $('file-input'),

  stage: $('stage'),
  preview: $('preview'),
  overlay: $('overlay'),
  btnRotate: $('btn-rotate'),
  btnRescan: $('btn-rescan'),
  btnReset: $('btn-reset'),
  progress: $('progress'),
  progressFill: $('progress-fill'),
  progressLabel: $('progress-label'),
  btnCancel: $('btn-cancel'),

  output: $('output'),
  text: $('text'),
  stats: $('stats'),
  btnCopy: $('btn-copy'),
  btnShare: $('btn-share'),
  btnDownload: $('btn-download'),
  optParagraphs: $('opt-paragraphs'),

  optLang: $('opt-lang'),
  optPsm: $('opt-psm'),
  optEngine: $('opt-engine'),
  optEngineNative: $('opt-engine-native'),
  engineNote: $('engine-note'),
  optEnhance: $('opt-enhance'),
  optBoxes: $('opt-boxes'),

  offlineBadge: $('offline-badge'),
  toast: $('toast'),
};

const state = {
  bitmap: null,
  rotation: 0,
  result: null,
  raw: '',
  busy: false,
  cancelled: false,
};

/* ---------------------------------------------------------------- settings */

const DEFAULTS = {
  lang: 'eng',
  psm: '3',
  engine: 'auto',
  enhance: true,
  boxes: true,
  join: false,
};
const STORE_KEY = 'img-to-text:settings';
const WARM_KEY = 'img-to-text:warm'; // set once the OCR runtime has been cached

const settings = { ...DEFAULTS, ...readJSON(STORE_KEY) };

function readJSON(key) {
  try {
    return JSON.parse(localStorage.getItem(key) ?? '{}');
  } catch {
    return {};
  }
}

function saveSettings() {
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify(settings));
  } catch {
    /* private mode — settings just won't persist */
  }
}

function applySettingsToForm() {
  el.optLang.value = settings.lang;
  el.optPsm.value = settings.psm;
  el.optEngine.value = settings.engine;
  el.optEnhance.checked = settings.enhance;
  el.optBoxes.checked = settings.boxes;
  el.optParagraphs.checked = settings.join;
}

/* ------------------------------------------------------------------- chrome */

let toastTimer;
function toast(message, { error = false } = {}) {
  clearTimeout(toastTimer);
  el.toast.textContent = message;
  el.toast.classList.toggle('error', error);
  el.toast.hidden = false;
  requestAnimationFrame(() => el.toast.classList.add('show'));
  toastTimer = setTimeout(() => {
    el.toast.classList.remove('show');
    toastTimer = setTimeout(() => {
      el.toast.hidden = true;
    }, 200);
  }, error ? 5000 : 1800);
}

function friendlyError(error) {
  const message = String(error?.message ?? error);
  if (/fetch|network|load|NetworkError/i.test(message) && !navigator.onLine) {
    return 'You are offline and this language has not been downloaded yet.';
  }
  if (/fetch|network|NetworkError|404/i.test(message)) {
    return 'Could not load the language data. Check your connection and try again.';
  }
  return `Could not read that image: ${message}`;
}

/* -------------------------------------------------------------- image input */

/** Accepts a File/Blob (picker, drop, paste, share) or an ImageBitmap (shutter). */
async function useSource(source) {
  if (!source) return;

  let bitmap;
  if (source instanceof ImageBitmap) {
    bitmap = source;
  } else {
    if (source.type && !source.type.startsWith('image/')) {
      toast('That file is not an image.', { error: true });
      return;
    }
    try {
      bitmap = await decode(source);
    } catch {
      toast('This browser could not decode that image (HEIC files often fail).', { error: true });
      return;
    }
  }

  state.bitmap?.close?.();
  state.bitmap = bitmap;
  state.rotation = 0;
  state.result = null;
  state.raw = '';

  // Release the camera as soon as we have the shot — it keeps the sensor (and the
  // battery, and the privacy indicator) from staying on while text is recognised.
  camera.stop();
  el.camera.hidden = true;
  el.source.hidden = true;
  el.stage.hidden = false;
  el.output.hidden = true;
  drawPreview();
  await scan();
}

function drawPreview() {
  render(el.preview, state.bitmap, { rotation: state.rotation, enhance: settings.enhance });
  drawBoxes(settings.boxes ? state.result?.lines : null);
}

function drawBoxes(lines) {
  const svg = el.overlay;
  svg.setAttribute('viewBox', `0 0 ${el.preview.width} ${el.preview.height}`);
  svg.replaceChildren();
  if (!lines?.length) return;
  const ns = 'http://www.w3.org/2000/svg';
  for (const { bbox } of lines) {
    const rect = document.createElementNS(ns, 'rect');
    rect.setAttribute('x', bbox.x0);
    rect.setAttribute('y', bbox.y0);
    rect.setAttribute('width', Math.max(1, bbox.x1 - bbox.x0));
    rect.setAttribute('height', Math.max(1, bbox.y1 - bbox.y0));
    rect.setAttribute('rx', 3);
    svg.appendChild(rect);
  }
}

async function reset() {
  state.bitmap?.close?.();
  Object.assign(state, { bitmap: null, rotation: 0, result: null, raw: '' });
  drawBoxes(null);
  el.cameraInput.value = '';
  el.fileInput.value = '';
  el.stage.hidden = true;
  el.output.hidden = true;
  await showStart();
}

/* ------------------------------------------------------------- camera view */

let torchOn = false;

/** The landing view: viewfinder on a phone, file picker everywhere else. */
async function showStart() {
  if (TOUCH && camera.supported()) await showCamera();
  else showPicker();
}

async function showCamera() {
  if (!camera.supported()) {
    showPicker('This browser will only open the camera over https.');
    return;
  }
  if ((await camera.permission()) === 'denied') {
    showPicker('Camera access is blocked for this site — pick a photo instead, or re-allow the camera in your browser’s site settings.');
    return;
  }

  el.source.hidden = true;
  el.stage.hidden = true;
  el.output.hidden = true;
  el.camera.hidden = false;
  el.btnShutter.disabled = true;
  torchOn = false;
  el.btnTorch.setAttribute('aria-pressed', 'false');

  try {
    await camera.start(el.viewfinder);
    el.btnShutter.disabled = false;
    el.btnTorch.hidden = !camera.hasTorch();
  } catch (error) {
    showPicker(cameraProblem(error));
  }
}

function showPicker(note) {
  camera.stop();
  el.camera.hidden = true;
  el.stage.hidden = true;
  el.output.hidden = true;
  el.source.hidden = false;
  el.cameraNote.hidden = !note;
  if (note) el.cameraNote.textContent = note;
  el.btnBackToCamera.hidden = !(TOUCH && camera.supported());
}

function cameraProblem(error) {
  switch (error?.name) {
    case 'NotAllowedError':
      return 'Camera permission was declined, so pick a photo instead.';
    case 'NotFoundError':
    case 'OverconstrainedError':
      return 'No camera found on this device — pick a photo instead.';
    case 'NotReadableError':
      return 'The camera is busy in another app. Close it and try again, or pick a photo.';
    default:
      console.warn('camera unavailable', error);
      return 'The camera could not be started, so pick a photo instead.';
  }
}

/* --------------------------------------------------------------------- scan */

function setProgress({ stage, progress }) {
  el.progressLabel.textContent = typeof progress === 'number' && progress > 0
    ? `${stage} ${Math.round(progress * 100)}%`
    : `${stage}…`;
  el.progressFill.style.width = `${Math.round((progress ?? 0) * 100)}%`;
}

async function scan() {
  if (state.busy || !state.bitmap) return;
  state.busy = true;
  state.cancelled = false;
  el.progress.hidden = false;
  el.btnRescan.disabled = true;
  setProgress({ stage: 'Starting', progress: 0 });

  try {
    const result = await ocr.recognize(el.preview, {
      base: BASE,
      lang: settings.lang,
      psm: settings.psm,
      engine: settings.engine,
      onProgress: setProgress,
    });

    state.result = result;
    state.raw = ocr.clean(result.text);
    showResult();
    markWarm();

    if (!state.raw) toast('No text found in that image.', { error: true });
  } catch (error) {
    if (!state.cancelled) {
      console.error(error);
      toast(friendlyError(error), { error: true });
    }
  } finally {
    state.busy = false;
    el.progress.hidden = true;
    el.btnRescan.disabled = false;
  }
}

function showResult() {
  el.text.value = settings.join ? ocr.joinWrappedLines(state.raw) : state.raw;
  el.output.hidden = false;
  updateStats();
  drawBoxes(settings.boxes ? state.result.lines : null);
}

function updateStats() {
  if (!state.result) return;
  el.stats.textContent = ocr.summarise({ ...state.result, text: el.text.value });
}

async function cancel() {
  state.cancelled = true;
  await ocr.terminate();
  toast('Scan cancelled');
}

/* ------------------------------------------------------------------ actions */

async function copyText() {
  const text = el.text.value;
  if (!text) return;
  try {
    await navigator.clipboard.writeText(text);
    toast('Copied to clipboard');
  } catch {
    // Clipboard API needs a secure context; this still works on plain http.
    el.text.focus();
    el.text.select();
    const ok = document.execCommand?.('copy');
    toast(ok ? 'Copied to clipboard' : 'Copy failed — select the text and copy manually', { error: !ok });
  }
}

async function shareText() {
  try {
    await navigator.share({ text: el.text.value, title: 'Scanned text' });
  } catch (error) {
    if (error?.name !== 'AbortError') toast('Sharing failed', { error: true });
  }
}

function downloadText() {
  const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
  const url = URL.createObjectURL(new Blob([el.text.value], { type: 'text/plain;charset=utf-8' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = `scan-${stamp}.txt`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

async function pickFile() {
  // File System Access gives a nicer desktop dialog; Android Chromium does not have
  // it, and there the hidden <input> is the right thing anyway.
  if (window.showOpenFilePicker) {
    try {
      const [handle] = await window.showOpenFilePicker({
        types: [{ description: 'Images', accept: { 'image/*': ['.png', '.jpg', '.jpeg', '.webp', '.gif', '.bmp', '.avif'] } }],
        excludeAcceptAllOption: false,
        multiple: false,
      });
      await useSource(await handle.getFile());
      return;
    } catch (error) {
      if (error?.name === 'AbortError') return;
      // Anything else (e.g. blocked by permissions policy): fall through.
    }
  }
  el.fileInput.click();
}

/* -------------------------------------------------------- platform plumbing */

function markWarm() {
  try {
    localStorage.setItem(WARM_KEY, '1');
  } catch {
    /* ignore */
  }
  el.firstRun.hidden = true;
  updateOfflineBadge();
}

function updateOfflineBadge() {
  let warm = false;
  try {
    warm = localStorage.getItem(WARM_KEY) === '1';
  } catch {
    /* storage can be blocked entirely; the badge is cosmetic */
  }
  el.offlineBadge.hidden = !(warm && navigator.serviceWorker?.controller);
  el.firstRun.hidden = warm || settings.engine === 'native';
}

/**
 * An image shared into the app from Android's share sheet, stashed by the SW.
 * Returns true when it took over the view, so boot does not also open the camera.
 */
async function consumeSharedImage() {
  const url = new URL(location.href);
  if (!url.searchParams.has('shared')) return false;
  url.searchParams.delete('shared');
  history.replaceState(null, '', url);
  try {
    const cache = await caches.open(SHARE_CACHE);
    const response = await cache.match(SHARE_CACHE);
    if (!response) return false;
    await cache.delete(SHARE_CACHE);
    await useSource(await response.blob());
    return true;
  } catch (error) {
    console.warn('shared image unavailable', error);
    return false;
  }
}

function registerServiceWorker() {
  if (!('serviceWorker' in navigator) || !window.isSecureContext) return;
  // Keep the SW out of the way while developing on localhost unless asked for.
  const local = ['localhost', '127.0.0.1', '[::1]'].includes(location.hostname);
  if (local && !new URLSearchParams(location.search).has('sw')) return;
  navigator.serviceWorker
    .register(new URL('sw.js', BASE), { scope: BASE.pathname })
    .catch((error) => console.warn('service worker registration failed', error));
}

/* -------------------------------------------------------------------- events */

el.btnShutter.addEventListener('click', async () => {
  if (el.btnShutter.disabled) return;
  el.btnShutter.disabled = true;
  try {
    await useSource(await camera.capture(el.viewfinder));
  } catch (error) {
    console.error(error);
    toast('Could not take that photo — try again.', { error: true });
  } finally {
    // Only re-arm if we are still looking through the viewfinder; a successful shot
    // has already moved on to the result view.
    if (!el.camera.hidden) el.btnShutter.disabled = false;
  }
});

el.btnTorch.addEventListener('click', async () => {
  try {
    await camera.setTorch(!torchOn);
    torchOn = !torchOn;
    el.btnTorch.setAttribute('aria-pressed', String(torchOn));
  } catch {
    toast('This camera has no light that can be switched on.', { error: true });
    el.btnTorch.hidden = true;
  }
});

el.btnUploadInstead.addEventListener('click', () => showPicker());
el.btnBackToCamera.addEventListener('click', showCamera);

el.btnCamera.addEventListener('click', () => el.cameraInput.click());
el.btnChoose.addEventListener('click', pickFile);
el.cameraInput.addEventListener('change', () => useSource(el.cameraInput.files[0]));
el.fileInput.addEventListener('change', () => useSource(el.fileInput.files[0]));

// Hand the camera back to the OS while the tab is in the background.
document.addEventListener('visibilitychange', () => {
  if (document.hidden) camera.stop();
  else if (!el.camera.hidden) showCamera();
});

el.btnRotate.addEventListener('click', async () => {
  state.rotation = (state.rotation + 90) % 360;
  state.result = null;
  drawPreview();
  await scan();
});
el.btnRescan.addEventListener('click', scan);
el.btnReset.addEventListener('click', reset);
el.btnCancel.addEventListener('click', cancel);

el.btnCopy.addEventListener('click', copyText);
el.btnShare.addEventListener('click', shareText);
el.btnDownload.addEventListener('click', downloadText);
el.text.addEventListener('input', updateStats);

el.optParagraphs.addEventListener('change', () => {
  settings.join = el.optParagraphs.checked;
  saveSettings();
  if (state.result) {
    el.text.value = settings.join ? ocr.joinWrappedLines(state.raw) : state.raw;
    updateStats();
  }
});

el.optBoxes.addEventListener('change', () => {
  settings.boxes = el.optBoxes.checked;
  saveSettings();
  drawBoxes(settings.boxes ? state.result?.lines : null);
});

el.optEnhance.addEventListener('change', async () => {
  settings.enhance = el.optEnhance.checked;
  saveSettings();
  if (!state.bitmap) return;
  drawPreview();
  await scan();
});

for (const [node, key] of [
  [el.optLang, 'lang'],
  [el.optPsm, 'psm'],
  [el.optEngine, 'engine'],
]) {
  node.addEventListener('change', async () => {
    settings[key] = node.value;
    saveSettings();
    updateOfflineBadge();
    if (state.bitmap) await scan();
  });
}

// Drag & drop anywhere on the page.
for (const type of ['dragenter', 'dragover']) {
  window.addEventListener(type, (event) => {
    if (!event.dataTransfer?.types.includes('Files')) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = 'copy';
    el.dropzone.classList.add('dragover');
  });
}
for (const type of ['dragleave', 'dragend']) {
  window.addEventListener(type, (event) => {
    if (event.relatedTarget) return;
    el.dropzone.classList.remove('dragover');
  });
}
window.addEventListener('drop', (event) => {
  const file = imageFromTransfer(event.dataTransfer);
  el.dropzone.classList.remove('dragover');
  if (!file) return;
  event.preventDefault();
  useSource(file);
});

// Paste a screenshot straight in.
window.addEventListener('paste', (event) => {
  if (event.target === el.text) return; // let people paste into the result box
  const file = imageFromTransfer(event.clipboardData);
  if (!file) return;
  event.preventDefault();
  useSource(file);
});

// Desktop "open with" (manifest file_handlers).
window.launchQueue?.setConsumer(async ({ files }) => {
  if (files?.length) await useSource(await files[0].getFile());
});

navigator.serviceWorker?.addEventListener?.('controllerchange', updateOfflineBadge);

/* --------------------------------------------------------------------- boot */

async function boot() {
  applySettingsToForm();

  if (ocr.engines.native.available()) {
    el.optEngineNative.hidden = false;
    el.engineNote.textContent = 'Your browser exposes the native TextDetector, so scans can use it and fall back to Tesseract.';
  } else if (settings.engine === 'native') {
    settings.engine = 'auto'; // stale preference from another browser/profile
    el.optEngine.value = 'auto';
  }

  el.btnShare.hidden = typeof navigator.share !== 'function';
  updateOfflineBadge();
  registerServiceWorker();

  // A shared image goes straight to the result, so don't also open the camera.
  if (await consumeSharedImage()) return;
  await showStart();
}

boot();
