/**
 * Tesseract (WebAssembly) engine — the one that actually has to work everywhere.
 *
 * The whole runtime is vendored under `vendor/` and loaded lazily on first scan, so
 * the app shell stays a few kB and nothing is fetched from a third party. Tesseract
 * spawns its own worker thread, so recognition never blocks the UI.
 */

const CDN = 'https://cdn.jsdelivr.net/npm/@tesseract.js-data';
const CDN_VARIANT = '4.0.0_best_int'; // what tesseract.js 7 expects for LSTM-only data

export const id = 'wasm';
export const label = 'On-device (Tesseract)';

export const available = () => typeof WebAssembly !== 'undefined' && typeof Worker !== 'undefined';

/** Human-readable stages, keyed by the status strings tesseract.js emits. */
const STATUS = {
  'loading tesseract core': 'Loading engine',
  'initializing tesseract': 'Starting engine',
  'initialized tesseract': 'Starting engine',
  'loading language traineddata': 'Loading language',
  'loading language traineddata (from cache)': 'Loading language',
  'loaded language traineddata': 'Loading language',
  'initializing api': 'Preparing',
  'initialized api': 'Preparing',
  'recognizing text': 'Reading text',
};

let lib = null; // the lazily imported tesseract.js module
let current = null; // { worker, lang, langPath }
let progressSink = null; // set per-run so a reused worker reports to the right caller
let abortPending = null; // rejects the in-flight scan when the worker is torn down

async function load(base) {
  if (!lib) {
    const url = new URL('vendor/tesseract/tesseract.esm.min.js', base).href;
    lib = (await import(/* webpackIgnore: true */ url)).default;
  }
  return lib;
}

function report(stage, progress) {
  progressSink?.({ stage, progress });
}

async function createWorker(base, lang, langPath) {
  const Tesseract = await load(base);
  const worker = await Tesseract.createWorker(lang, 1 /* OEM.LSTM_ONLY */, {
    workerPath: new URL('vendor/tesseract/worker.min.js', base).href,
    corePath: new URL('vendor/tesseract-core/', base).href,
    langPath,
    // Load the worker straight from its own URL rather than a blob: shim, so the
    // service worker can serve it (and its core) from cache when offline.
    workerBlobURL: false,
    gzip: true,
    logger: ({ status, progress }) => report(STATUS[status] ?? 'Working', progress),
  });
  return worker;
}

/**
 * Get a worker for `lang`, reusing the previous one when possible — re-initialising
 * costs a couple of seconds on a phone, and most people scan several images in a row.
 */
async function disposeWorker() {
  const worker = current?.worker;
  current = null;
  if (worker) await worker.terminate().catch(() => {});
}

async function getWorker(base, lang) {
  if (current?.lang === lang) return current.worker;
  // Swap workers without touching the abort signal — this runs *inside* a scan.
  await disposeWorker();

  const local = new URL('vendor/tessdata', base).href;
  const remote = `${CDN}/${lang}/${CDN_VARIANT}`;
  // English ships with the app; anything else comes from the CDN and is then cached
  // by tesseract.js in IndexedDB. If the vendored copy is missing (e.g. `bun run
  // vendor` could not reach the network at build time) fall back to the CDN too.
  const attempts = lang === 'eng' ? [local, remote] : [remote];

  let lastError;
  for (const langPath of attempts) {
    try {
      const worker = await createWorker(base, lang, langPath);
      current = { worker, lang, langPath };
      return worker;
    } catch (error) {
      lastError = error;
      await disposeWorker();
    }
  }
  throw lastError instanceof Error ? lastError : new Error(String(lastError ?? 'engine failed to start'));
}

/** Flatten tesseract's block→paragraph→line tree into the shape the UI wants. */
function toLines(page) {
  const lines = [];
  for (const block of page.blocks ?? []) {
    for (const paragraph of block.paragraphs ?? []) {
      for (const line of paragraph.lines ?? []) {
        const text = line.text.replace(/\s+$/, '');
        if (text) lines.push({ text, confidence: line.confidence, bbox: line.bbox });
      }
    }
  }
  return lines;
}

export async function recognize(image, { base, lang = 'eng', psm = '3', onProgress } = {}) {
  progressSink = onProgress;

  const scan = async () => {
    const worker = await getWorker(base, lang);
    await worker.setParameters({
      tessedit_pageseg_mode: String(psm),
      preserve_interword_spaces: '1',
      // Photos carry no DPI metadata; telling tesseract 300 stops it guessing badly.
      user_defined_dpi: '300',
    });

    const { data } = await worker.recognize(image, {}, { text: true, blocks: true });
    return {
      engine: id,
      text: data.text ?? '',
      confidence: data.confidence,
      lines: toLines(data),
    };
  };

  // Killing the worker leaves tesseract.js's pending promise permanently unsettled,
  // which would wedge the UI, so race the scan against an explicit abort signal.
  const aborted = new Promise((_, reject) => {
    abortPending = reject;
  });

  try {
    return await Promise.race([scan(), aborted]);
  } finally {
    abortPending = null;
    progressSink = null;
  }
}

/** There is no in-flight abort in tesseract.js; dropping the worker is the cancel. */
export async function terminate() {
  abortPending?.(new DOMException('Scan cancelled', 'AbortError'));
  abortPending = null;
  await disposeWorker();
}
