/**
 * Image handling, all with platform APIs: createImageBitmap for decoding (off the
 * main thread, and it applies EXIF orientation for us) and a 2D canvas for the
 * scale / rotate / clean-up pass that feeds the OCR engine.
 */

/**
 * Phone cameras produce 12 MP+ images. Tesseract gets slower roughly linearly with
 * pixel count and gains nothing past the point where glyphs are ~30px tall, so cap
 * the working image. This is the single biggest lever on mobile scan time.
 */
const MAX_PIXELS = 4.2e6; // ~2600 x 1600

/** Decode a File/Blob into an ImageBitmap with EXIF rotation already applied. */
export async function decode(blob) {
  try {
    return await createImageBitmap(blob, { imageOrientation: 'from-image' });
  } catch {
    // Some Chromium builds reject the options bag for certain formats; retry bare.
    return await createImageBitmap(blob);
  }
}

/**
 * Draw `bitmap` into `canvas`, scaled down to the pixel budget and rotated by
 * `rotation` (a multiple of 90°). Returns the canvas.
 */
export function render(canvas, bitmap, { rotation = 0, enhance = false } = {}) {
  const turned = rotation % 180 !== 0;
  const scale = Math.min(1, Math.sqrt(MAX_PIXELS / (bitmap.width * bitmap.height)));
  const w = Math.max(1, Math.round(bitmap.width * scale));
  const h = Math.max(1, Math.round(bitmap.height * scale));

  canvas.width = turned ? h : w;
  canvas.height = turned ? w : h;

  const ctx = canvas.getContext('2d', { willReadFrequently: enhance, alpha: false });
  ctx.imageSmoothingQuality = 'high';
  ctx.save();
  ctx.translate(canvas.width / 2, canvas.height / 2);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.drawImage(bitmap, -w / 2, -h / 2, w, h);
  ctx.restore();

  if (enhance) contrast(ctx, canvas.width, canvas.height);
  return canvas;
}

/**
 * Greyscale + histogram stretch. Photographed paper is usually low-contrast and
 * unevenly lit; pinning the 2nd/98th percentile to black/white recovers most of it
 * without the artefacts a hard threshold would introduce on shadowed pages.
 */
function contrast(ctx, width, height) {
  const image = ctx.getImageData(0, 0, width, height);
  const px = image.data;
  const histogram = new Uint32Array(256);

  for (let i = 0; i < px.length; i += 4) {
    // Rec. 601 luma, integer-ish for speed
    const y = (px[i] * 77 + px[i + 1] * 150 + px[i + 2] * 29) >> 8;
    px[i] = y;
    histogram[y]++;
  }

  const total = width * height;
  const cut = total * 0.02;
  let low = 0;
  let high = 255;
  for (let sum = 0, v = 0; v < 256; v++) {
    sum += histogram[v];
    if (sum > cut) {
      low = v;
      break;
    }
  }
  for (let sum = 0, v = 255; v >= 0; v--) {
    sum += histogram[v];
    if (sum > cut) {
      high = v;
      break;
    }
  }
  if (high - low < 24) return; // near-flat image: leave it alone rather than amplify noise

  const lut = new Uint8Array(256);
  for (let v = 0; v < 256; v++) {
    lut[v] = Math.max(0, Math.min(255, Math.round(((v - low) * 255) / (high - low))));
  }
  for (let i = 0; i < px.length; i += 4) {
    const y = lut[px[i]];
    px[i] = y;
    px[i + 1] = y;
    px[i + 2] = y;
  }
  ctx.putImageData(image, 0, 0);
}

/** Best-effort conversion of anything droppable/pastable into an image Blob. */
export function imageFromTransfer(dataTransfer) {
  for (const item of dataTransfer?.items ?? []) {
    if (item.kind === 'file' && item.type.startsWith('image/')) return item.getAsFile();
  }
  for (const file of dataTransfer?.files ?? []) {
    if (file.type.startsWith('image/')) return file;
  }
  return null;
}
