/**
 * Live camera capture via getUserMedia — the default way in on a phone.
 *
 * Prefers ImageCapture.takePhoto() for the shot, which gives the full-resolution
 * still rather than the downscaled preview frame; that difference is worth real
 * accuracy on small text. Falls back to grabbing the video frame when the platform
 * has no ImageCapture, refuses the call, or takes too long to fire the shutter.
 */

let stream = null;

export const supported = () =>
  Boolean(globalThis.isSecureContext && navigator.mediaDevices?.getUserMedia);

const videoTrack = () => stream?.getVideoTracks()?.[0] ?? null;

/** 'granted' | 'prompt' | 'denied' | 'unknown' — used to avoid a pointless prompt. */
export async function permission() {
  try {
    const status = await navigator.permissions?.query({ name: 'camera' });
    return status?.state ?? 'unknown';
  } catch {
    // Not every browser knows the 'camera' permission name; just try the camera.
    return 'unknown';
  }
}

export async function start(video) {
  stop();
  stream = await navigator.mediaDevices.getUserMedia({
    audio: false,
    video: {
      // `ideal`, not `exact`: a laptop with only a front camera should still work.
      facingMode: { ideal: 'environment' },
      width: { ideal: 1920 },
      height: { ideal: 1080 },
    },
  });

  video.srcObject = stream;
  video.setAttribute('playsinline', ''); // stop Android/iOS taking the video fullscreen
  await video.play().catch(() => {});
  await frameReady(video);
  return stream;
}

export function stop() {
  for (const track of stream?.getTracks() ?? []) track.stop();
  stream = null;
}

/** Resolve once the stream has produced a frame, so captures cannot be blank. */
function frameReady(video) {
  if (video.videoWidth > 0) return Promise.resolve();
  return new Promise((resolve) => {
    const done = () => {
      video.removeEventListener('loadeddata', done);
      resolve();
    };
    video.addEventListener('loadeddata', done, { once: true });
    setTimeout(done, 3000);
  });
}

/* --- torch: genuinely useful when reading text in a dim room ---------------- */

export const hasTorch = () => Boolean(videoTrack()?.getCapabilities?.().torch);

export async function setTorch(on) {
  await videoTrack()?.applyConstraints({ advanced: [{ torch: on }] });
}

/* --- the shutter ------------------------------------------------------------ */

const withTimeout = (promise, ms) =>
  Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error('shutter timed out')), ms)),
  ]);

export async function capture(video) {
  const track = videoTrack();
  if (track && typeof globalThis.ImageCapture === 'function') {
    try {
      const blob = await withTimeout(new globalThis.ImageCapture(track).takePhoto(), 4000);
      if (blob?.size) return blob;
    } catch {
      // Plenty of Android devices advertise ImageCapture and then fail on it.
    }
  }
  return createImageBitmap(video);
}
