/**
 * Native engine — the Shape Detection API's TextDetector, which hands the image to
 * whatever OCR the OS already ships (ML Kit on Android). When it is there it is an
 * order of magnitude faster than WASM and costs no download.
 *
 * It is *not* enabled by default in any shipping browser: on Chromium it sits behind
 * chrome://flags/#enable-experimental-web-platform-features, and it never reached a
 * standard. So this is strictly an opportunistic fast path — engine selection always
 * has the WASM engine to fall back to, including when detection returns nothing.
 */

export const id = 'native';
export const label = 'Native TextDetector';

export const available = () => typeof globalThis.TextDetector === 'function';

export async function recognize(image, { onProgress } = {}) {
  onProgress?.({ stage: 'Reading text', progress: 0.2 });
  const detector = new globalThis.TextDetector();
  const blocks = await detector.detect(image);
  onProgress?.({ stage: 'Reading text', progress: 1 });

  const lines = blocks
    .map((block) => {
      const box = block.boundingBox;
      return {
        text: block.rawValue,
        // The API reports no per-block confidence; treat a detection as certain so
        // the UI does not show a misleadingly precise number.
        confidence: null,
        bbox: { x0: box.x, y0: box.y, x1: box.x + box.width, y1: box.y + box.height },
      };
    })
    // Detections come back in no guaranteed order; approximate reading order by
    // banding on y (so words on the same line stay together) then sorting by x.
    .sort((a, b) => {
      const band = Math.max(24, (a.bbox.y1 - a.bbox.y0) * 0.6);
      const dy = a.bbox.y0 - b.bbox.y0;
      return Math.abs(dy) > band ? dy : a.bbox.x0 - b.bbox.x0;
    });

  return {
    engine: id,
    text: lines.map((line) => line.text).join('\n'),
    confidence: null,
    lines,
  };
}

export async function terminate() {}
